# -*- coding: utf-8 -*-
"""Publish the accepted v6 graphs, review evidence and full retained ancillary content."""
import argparse,collections,html,json
from reconcile_pdf_sources import ROOT,V5,OUT
from build_physical_graphs import read,lines,write,sha,rel
from publish_pdf_paragraph_graphs import page,VIEWER,COMPARE

EXTRA=r'''
const el=id=>document.getElementById(id),bid=new URLSearchParams(location.search).get('book');let all=[];
const labels={program_listing:'程序清单',table_of_contents:'目录',index_entries:'索引条目',glossary_entries:'词汇条目',figure_caption:'修正后的图注',publication_metadata:'出版信息',publisher_book_list:'出版书目',watermark:'水印',code:'代码',caption:'图注',formula:'公式',equation:'公式',footnote:'脚注',metadata:'元信息',heading_text:'标题文字',bibliography:'参考文献'};
function render(){let q=el('query').value.trim(),t=el('kind').value;let hits=all.filter(n=>(t==='all'||t==='retyped'&&n.previous_type==='paragraph'||n.type===t)&&(!q||n.text.includes(q)));el('status').textContent='匹配 '+hits.length+' 条，显示前 200 条。完整内容均在全量图数据中。';el('items').replaceChildren();for(let n of hits.slice(0,200)){let a=document.createElement('article'),m=document.createElement('small'),p=document.createElement('pre'),link=document.createElement('a');m.textContent=(labels[n.type]||n.type)+' · PDF '+(n.pdf_pages||[...new Set(n.source_spans.map(s=>s.page_pdf))]).join('、')+(n.previous_type?' · 本轮恢复内容类型':'');p.textContent=n.text;link.href='原页对照.html?book='+bid+'&node='+encodeURIComponent(n.id);link.textContent='查看原页 →';a.append(m,p,link);el('items').append(a)}}
(async()=>{try{let g=await(await fetch(bid+'/text_graph.json')).json();el('title').textContent='附属内容';el('back').href='层级查看.html?book='+bid;el('raw').href=bid+'/text_graph.json';all=g.nodes.filter(n=>n.type!=='paragraph');for(let t of [...new Set(all.map(n=>n.type))].sort()){let o=document.createElement('option');o.value=t;o.textContent=labels[t]||t;el('kind').append(o)}el('kind').onchange=render;el('search').onclick=render;render()}catch(e){el('title').textContent=e.message}})();
'''

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--preview',action='store_true');args=parser.parse_args()
    m=read(OUT/'manifest.json');v=read(OUT/'验收结果.json');s=m['summary']
    assert len(m['books'])==24 and v['status']=='passed' and v['manifest_sha256']==sha(OUT/'manifest.json') and s['review_needed']==0
    reviews=read(OUT/'boundary_visual_review/visual_decisions.json');cases={c['case_id']:c for c in lines(OUT/'boundary_visual_review/cases.jsonl')}
    stats=collections.Counter(r['decision'] for r in reviews);types=collections.Counter();actual_parent_changes=0
    for b in m['books']:
        g=read(OUT/b['book_id']/'text_graph.json');types.update(n['type'] for n in g['nodes'] if n.get('previous_type')=='paragraph')
        actual_parent_changes+=sum(r['operation']=='assign_structural_parent' and r['old_parent']!=r['new_parent'] for r in lines(OUT/b['book_id']/'repair_ledger.jsonl'))
    reconciliation=[read(OUT/b['book_id']/'source_reconciliation_summary.json') for b in m['books']]
    write(OUT/'原页重定位汇总.json',{'books':reconciliation,'scope':'All 24 cached source reconciliation summaries; final body coverage is measured by acceptance report.'})
    summary={'books':24,**s,'actual_paragraph_parent_changes':actual_parent_changes,'retyped_nodes_preserved':dict(types),'visual_cases_reviewed':len(reviews),'visual_decisions':dict(stats),'known_review_queue_remaining':0,'verification_report':'验收结果.json','human_verified':False,'full_corpus_OCR_verified':False,'scope':'Full source and hierarchy checks plus assistant visual review of all 133 final flagged page-boundary cases; not a claim of exhaustive human annotation.'}
    write(OUT/'本轮修复汇总.json',summary)
    table=''.join('<tr><td><a href="层级查看.html?book='+b['book_id']+'">'+html.escape(b['book_title'])+'</a></td><td>'+format(b['paragraphs'],',')+'</td><td>'+str(b['structural_headings'])+'</td><td>'+str(b['review_needed'])+'</td><td><a href="附属内容.html?book='+b['book_id']+'">查看</a></td></tr>' for b in m['books'])
    cards='<div class="stats">'+''.join('<div class="stat"><b>'+format(n,',')+'</b>'+label+'</div>' for n,label in [(24,'本教材'),(s['paragraphs'],'正文段落'),(s['headings_located'],'已定位结构标题'),(len(reviews),'疑点原页对照'),(s['review_needed'],'本轮遗留待核项')])+'</div>'
    body='<span class="pill">原 PDF 自然段 · v6</span><h1>版面与章节归属修复结果</h1><p>保持书名 → 章 → 节 → 小节 → 段落的关系，按原书实际标题深度挂接；章、节开头尚未进入小节的正文保留在对应章、节下。</p><section>'+cards+'</section><section><h2>本轮处理结果</h2><p>全部 '+format(s['paragraphs'],',')+' 个正文段落均有完整的原 PDF 行位置依据，'+format(s['headings_located'],',')+' 个结构标题均已定位。修正编号列表、跨页续段、图文环绕和代码前后误合并；补回原页中的章标题并校正标题作用范围。</p><p>相对 v5，新增 '+str(s['added_internal_boundaries'])+' 处段落边界，合并 '+str(s['merged_record_boundaries'])+' 处错误断开的续段；另将 '+str(sum(types.values()))+' 个误标为正文的节点恢复为目录、程序、图注等类型。所有原始内容及旧节点到新节点的映射均保留，没有隔离或丢弃正文。</p><p>最后 '+str(len(reviews))+' 处跨页疑点已逐项查看原页并记录处理依据，本轮记录中的待核项已处理完。验收通过：源字符范围无缺失、无重复，原 PDF 未改变，段落均为单父节点的叶节点，章节关系无断链。</p><p class="muted">核验方式为全量程序检查与 AI 原页目视复核。当前结果可用于图谱构建和实验数据处理；它不表示全部 OCR 文字已逐字校对，也不等同于逐段人工标注的论文金标准。</p><div class="links"><a href="疑点处理记录.html">133 项原页处理记录</a><a href="验收结果.json">完整验收记录</a><a href="本轮修复汇总.json">修复统计</a><a href="全量正文段落.jsonl">全量正文段落</a><a href="层级数据清单.json">24 本层级数据</a></div></section><section><h2>选择教材</h2><table><thead><tr><th>教材</th><th>正文段落</th><th>结构标题</th><th>遗留待核项</th><th>附属内容</th></tr></thead><tbody>'+table+'</tbody></table></section>'
    for name in ['修复结果.html','层级结构入口.html']:(OUT/name).write_text(page('版面与章节归属修复 v6',body),encoding='utf-8')
    viewer=VIEWER.replace("'书前内容及章归属待核内容（'","'书前正文（'").replace("' · 章节归属待复核'","' · 章节归属待复核'").replace("'　原有质量标记保留'","'　存在具体待核项'")
    viewer=viewer.replace("'已检查原页版面，沿用当前边界'","'原页位置与章节范围已核验'")
    (OUT/'层级查看.html').write_text(page('章节树与原 PDF 自然段','<a href="修复结果.html">← 24 本修复结果</a><h1 id="title">读取中…</h1><p>点击章、节、小节展开自然段；每段可对照原 PDF。正文完整保留，本轮已记录的版面及归属疑点已处理。</p><p><a id="extra">查看目录、程序、图注等附属内容 →</a></p><section><input id="query" placeholder="查找章节或正文"><button id="search">查找并展开</button><button id="reset">收起全部</button><p id="status"></p></section><section id="tree"></section>',viewer+"\nel('extra').href='附属内容.html?book='+bid;"),encoding='utf-8')
    compare=COMPARE.replace("if(!n)throw Error('段落不存在');","if(!n){let full=await(await fetch(bid+'/text_graph.json')).json();n=full.nodes.find(x=>x.id===nid);if(n)n.path_ids=[bid,n.heading_id,n.id]}if(!n)throw Error('节点不存在');").replace("lookup[x].label","lookup[x]?.label||x").replace('for(let e of n.pdf_evidence)','for(let e of (n.pdf_evidence||[]))')
    compare=compare.replace("el('path').textContent=", "if(n.type!=='paragraph'){let ids=[];for(let cur=n.heading_id;cur&&lookup[cur];cur=lookup[cur].parent_id)ids.unshift(cur);n.path_ids=[...ids,n.id]}el('path').textContent=")
    compare=compare.replace("el('note').textContent='段落节点 '+nid+'。原始文本字符范围、PDF 行框和页码均保留在数据文件中。';", "el('note').textContent='已保留原 PDF 页码、行位置及源文本范围，可从完整图数据追溯。';if(n.type!=='paragraph'){el('back').href='附属内容.html?book='+bid;el('back').textContent='← 返回附属内容'}")
    (OUT/'原页对照.html').write_text(page('文本与原 PDF 对照','<a id="back">← 返回章节树</a><h1 id="title">读取中…</h1><p id="path"></p><div class="compare"><section><h2>图谱中的文本</h2><pre id="text"></pre><p id="note" class="muted"></p><a id="raw">完整图数据</a></section><section><h2>原 PDF 页面</h2><p id="pages" class="links"></p><p><a id="external" target="_blank">单独打开原 PDF</a></p><a id="imageLink" target="_blank"><img id="pdf" alt="原 PDF 页面，点击放大" style="width:100%;height:auto"></a></section></div>',compare),encoding='utf-8')
    (OUT/'附属内容.html').write_text(page('完整保留的附属内容','<a id="back">← 返回章节树</a><h1 id="title">附属内容</h1><p>目录、程序、公式、图注、索引等内容保留在完整图中，并标注各自类型。默认显示本轮从正文中识别出的内容。</p><p><a id="raw">下载完整图数据（含全部节点和图表资源）</a></p><section><select id="kind"><option value="retyped">本轮恢复类型的内容</option><option value="all">全部附属文本</option></select><input id="query" placeholder="查找文本"><button id="search">查找</button><p id="status"></p></section><section id="items"></section>',EXTRA),encoding='utf-8')
    names={'continue':'保留跨页续段','split':'按原页拆开','program_listing':'恢复程序类型','table_of_contents':'恢复目录类型','index_entries':'恢复索引类型','glossary_entries':'恢复词汇条目类型'}
    rows=''.join('<tr><td>'+str(r['case_id'])+'</td><td>'+html.escape(next(b['book_title'] for b in m['books'] if b['book_id']==cases[r['case_id']]['book_id']))+'</td><td>'+str(cases[r['case_id']]['previous_line']['pdf_page'])+' → '+str(cases[r['case_id']]['current_line']['pdf_page'])+'</td><td>'+names[r['decision']]+'</td><td>'+html.escape(r['reason'])+'</td><td><a target="_blank" href="boundary_visual_review/'+r['evidence_sheet']+'">原页证据</a></td></tr>' for r in reviews)
    (OUT/'疑点处理记录.html').write_text(page('133 项原页疑点处理记录','<a href="修复结果.html">← 修复结果</a><h1>133 项原页疑点处理记录</h1><p>以下为 AI 对原 PDF 页面图像的逐项目视复核。跨页续段、拆分和内容类型修正均写回图谱；图文环绕的两处正文续段也已重新连接。图片哈希与决定保存在 <a href="boundary_visual_review/visual_decisions.json">机器可读记录</a> 中。</p><section><table><tr><th>编号</th><th>教材</th><th>PDF 页</th><th>处理</th><th>依据</th><th>对照</th></tr>'+rows+'</table></section>'),encoding='utf-8')
    if args.preview:
        print(json.dumps({'preview':rel(OUT/'修复结果.html'),'summary':summary},ensure_ascii=False));return
    pointer_path=ROOT/'研究方案_20261002/24本文本图_当前版本.json';pointer=read(pointer_path)
    if not (OUT/'previous_current_pointer.json').exists():write(OUT/'previous_current_pointer.json',pointer)
    pointer.update(version='v6',previous_version='v5',data_directory=rel(OUT),manifest_path=rel(OUT/'manifest.json'),manifest_sha256=sha(OUT/'manifest.json'),report_path=rel(OUT/'修复结果.html'),repair_report_path=rel(OUT/'修复结果.html'),hierarchy_manifest_path=rel(OUT/'层级数据清单.json'),hierarchy_graph_filename='hierarchy_graph.json',full_paragraph_corpus_path=rel(OUT/'全量正文段落.jsonl'),full_corpus_natural_paragraph_verified=False,human_verified=False,known_review_queue_remaining=0,latest_corpus_audit={'conclusion_path':rel(OUT/'验收结果.json'),'acceptance':'source_and_physical_hierarchy_passed_all_logged_review_items_resolved','paragraphs':s['paragraphs'],'original_pdf_pages_processed':13187,'visual_review_cases':len(reviews),'visual_review_path':rel(OUT/'boundary_visual_review/visual_decisions.json')})
    write(pointer_path,pointer);print(json.dumps({'published':rel(OUT/'修复结果.html'),'summary':summary},ensure_ascii=False))

if __name__=='__main__':main()
